stmp1:			ds 41
ltmp0:			dw 0, 0

; numbers passed by address (read only)
llit_0:			dw 0, 0
llit_5000:			dw 5000, 0
llit_2:			dw 2, 0
llit_32767:			dw 32767, 0
lit_2:			dw 2
lit_0:			dw 0
lit_3:			dw 3
lit_255:			dw 255

