str0:			db "Nodes, 2-32767 (Return = 5000)? ", 0
str1:			db "Most is 32767", 0
str2:			db "Room for ", 0
str3:			db " nodes", 0
str4:			db "List of ", 0
str5:			db "T = turbo, N = normal, X = exit", 0
str6:			db "T", 0
str7:			db "N", 0
str8:			db "X", 0
str9:			db "Turbo", 0
str10:			db "Normal", 0
str11:			db 0
str12:			db ": ", 0
str13:			db " nodes...", 0
str14:			db "Done - stop the stopwatch", 0
str15:			db "in order", 0
str16:			db "NOT IN ORDER", 0
str17:			db "fill ", 0
str18:			db "  sort ", 0
str19:			db "  check ", 0
